sys_script.script:
(function executeRule(current) {
    var base = new GlideDateTime(current.preferred_date);
    var oneHourBefore = new GlideDateTime(base);
    var oneHourAfter = new GlideDateTime(base);
    oneHourBefore.subtract(60 * 60 * 1000); // -1h
    oneHourAfter.add(60 * 60 * 1000); // +1h

    gs.info('🕒 preferred_date: ' + base.getDisplayValue());
    gs.info('🔻 -1h: ' + oneHourBefore.getDisplayValue());
    gs.info('🔺 +1h: ' + oneHourAfter.getDisplayValue());

    var gr = new GlideRecord('x_1650712_4dot_m_0_employer_branding');
    gr.addQuery('platform', current.platform);
    gr.addQuery('preferred_date', '>=', oneHourBefore);
    gr.addQuery('preferred_date', '<=', oneHourAfter);
    gr.addQuery('sys_id', '!=', current.sys_id); // do not self compare
    gr.query();

    if (gr.next()) {
        gs.addErrorMessage('⚠️ There is already a post scheduled for this hour for the same platform: ' + gr.getValue('number'));
        current.setAbortAction(true);
    }
})(current);
